<script setup lang="ts">
/**
 * An anchored, non-modal surface for rich content (`design/components/popover.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/popover.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import {
  computed,
  inject,
  onBeforeUnmount,
  onMounted,
  provide,
  useId,
  useTemplateRef,
  watch,
} from 'vue'

import * as zag from '@zag-js/popover'
import { normalizeProps, useMachine } from '@zag-js/vue'

import {
  agentMember,
  anchorProps,
  syncTriggerAnchor,
  useDirection,
  useMediaQuery,
} from '@polymorph/vue'
import { usePresence } from '@polymorph/vue/motion'
import styles from '@polymorph/recipes/overlays/popover.module.css'
import sheet from '@polymorph/recipes/overlays/sheet.module.css'
import triggerAnchor from '@polymorph/recipes/overlays/trigger-anchor.module.css'

export type PopoverAlign = NonNullable<PopoverProps['align']>

export type PopoverSide = NonNullable<PopoverProps['side']>

export interface PopoverProps {
  align?: 'start' | 'center' | 'end'
  defaultOpen?: boolean
  /**
   * The panel's accessible name; required on purpose.
   */
  label: string
  open?: boolean
  /**
   * `'auto'` stays anchored at every width, because Popover is non-modal by contract and a
   * default must not change that on phones only. `'sheet'` is the app's opt-in: unchanged above
   * `30rem`, and a modal bottom sheet below it (the sheet presentation,
   * `design/components/README.md`), as the spec states.
   */
  presentation?: 'auto' | 'sheet'
  side?: 'bottom' | 'top' | 'right' | 'left'
}

defineOptions({ name: 'Popover', inheritAttrs: false })

const props = withDefaults(defineProps<PopoverProps>(), {
  align: 'start',
  defaultOpen: undefined,
  open: undefined,
  presentation: 'auto',
  side: 'bottom',
})
const emit = defineEmits<{ openChange: [open: boolean] }>()
defineSlots<{
  default: (props: Record<string, never>) => unknown
  trigger: (props: Record<string, never>) => unknown
}>()
const uid = useId()
const lender = inject<{ element?: () => Element | null | undefined } | undefined>(
  'polymorph:borrowed',
  undefined,
)
provide('polymorph:borrowed', undefined)
const anchor = useTemplateRef<HTMLElement>('anchor')
const panel = useTemplateRef<HTMLElement>('panel')
const scrim = useTemplateRef<HTMLElement>('scrim')
const sheetPanel = useTemplateRef<HTMLElement>('sheetPanel')
const phone = useMediaQuery('phone')
const sheeting = computed(() => props.presentation === 'sheet' && phone.value)
const documentDirection = useDirection(() => anchor.value)
const service = useMachine(
  zag.machine,
  computed(() => ({
    id: uid,
    dir: documentDirection.value,
    open: props.open,
    defaultOpen: props.defaultOpen,
    modal: sheeting.value,
    positioning: {
      placement: props.align === 'center' ? props.side : `${props.side}-${props.align}`,
      offset: { mainAxis: 4 },
    },
    onOpenChange: (details) => {
      emit('openChange', details.open)
    },
  })),
)
const api = computed(() => zag.connect(service, normalizeProps))
const present = usePresence(() => api.value.open && !sheeting.value, panel)
const sheetPresent = usePresence(
  () => api.value.open && sheeting.value,
  sheetPanel,
  'sheet.panel',
  { sheetSide: 'bottom' },
)
const scrimPresent = usePresence(() => api.value.open && sheeting.value, scrim, 'dialog.scrim')
const effect1 = () => {
  syncTriggerAnchor(anchor.value, api.value.getTriggerProps(), api.value.open)
}
onMounted(effect1)
watch(() => api.value.open, effect1, { flush: 'post' })
const effect2 = () => {
  lender && (lender.element = () => panel.value ?? sheetPanel.value)
}
onMounted(effect2)
let release3: (() => void) | undefined
const effect3 = () => {
  release3?.()
  const ran = lender
    ? () => {}
    : agentMember({
        member: 'Popover',
        element: () => panel.value ?? sheetPanel.value,
        state: () => ({ open: api.value.open }),
        actions: { close: () => api.value.open && api.value.setOpen(false) },
      })
  release3 = () => {
    ran()
  }
}
onMounted(effect3)
onBeforeUnmount(() => release3?.())
</script>

<template>
  <span ref="anchor" v-bind="anchorProps(api.getTriggerProps())" :class="triggerAnchor.anchor">
    <slot name="trigger" />
  </span>
  <Teleport to="body">
    <div v-if="present" v-bind="api.getPositionerProps()">
      <!-- panel -->
      <div
        ref="panel"
        v-bind="api.getContentProps()"
        :class="styles.panel"
        :style="{ '--radix-popover-content-transform-origin': 'var(--transform-origin)' }"
        :hidden="undefined"
        :aria-labelledby="undefined"
        :aria-describedby="undefined"
        :aria-label="label"
        data-member="popover"
      >
        <slot />
      </div>
    </div>
    <div
      v-if="scrimPresent"
      ref="scrim"
      :class="sheet.scrim"
      :data-state="api.open ? 'open' : 'closed'"
    />
    <div v-if="sheetPresent" :class="sheet.positioner">
      <div
        ref="sheetPanel"
        v-bind="api.getContentProps()"
        :class="sheet.panel"
        :hidden="undefined"
        :aria-labelledby="undefined"
        :aria-describedby="undefined"
        :aria-label="label"
        data-presentation="sheet"
      >
        <!-- panel -->
        <div :class="styles.sheetBody" data-member="popover">
          <slot />
        </div>
      </div>
    </div>
  </Teleport>
</template>
